import {PipelineEngine,type RunState} from '../engine';
import {example} from '../examples';
import {serialize,importEdit,importRun} from '../serialize';
import {synthetic} from '../synthetic';
import {sampleMedia} from './sample-media';
const host=document.querySelector<HTMLElement>('#harness')!,engine=new PipelineEngine();let state:RunState|undefined;
host.innerHTML='<select id="recipe"><option value="remove">Remove long silences</option><option value="speaker">Speaker focus</option><option value="cross">Cross-revision tag</option></select><button id="load">Load recipe</button><button id="run">Run JSON</button><button id="continue">Continue</button><button id="save">Export run</button><input id="restore" type="file" accept=".json"><textarea id="graph" aria-label="Graph JSON"></textarea><div id="samples"></div><pre id="status"></pre><div id="results"></div>';
const $=<T extends HTMLElement>(id:string)=>document.getElementById(id) as T,esc=(v:unknown)=>String(v).replace(/[&<>"']/g,c=>`&#${c.charCodeAt(0)};`);
function render(){if(!state)return;$('status').textContent=state.status+(state.error?`\n${state.error.message}`:'');const result=$('results');result.replaceChildren();for(const [id,outputs]of Object.entries(state.outputs)){const section=document.createElement('section');section.innerHTML=`<h2>${esc(id)}</h2>`;for(const value of Object.values(outputs)){if('values'in value){const step=Math.max(1,Math.floor(value.values.length/500)),points=Array.from(value.values).filter((_,i)=>i%step===0).map((v,i)=>`${i*2},${80-v*60}`).join(' ');section.innerHTML+=`<p>${esc(value.kind)} · ${value.values.length} samples</p><svg viewBox="0 0 1000 90" aria-label="Signal chart"><polyline points="${points}" fill="none" stroke="#9ee8bd"/></svg>`;}else{const pre=document.createElement('pre');pre.textContent=JSON.stringify(value,null,2);section.append(pre);}}result.append(section);}const table=document.createElement('table');table.innerHTML='<tr><th>Operation</th><th>Confidence</th><th>Mode/status</th><th>Resolve</th></tr>';for(const op of state.decisions){const row=table.insertRow();row.innerHTML=`<td>${esc(op.summary)}</td><td>${op.confidence.toFixed(2)}</td><td>${esc(op.mode)} / ${esc(op.status)}</td>`;const cell=row.insertCell();for(const decision of ['accept','reject','skip'] as const){const b=document.createElement('button');b.textContent=decision;b.disabled=!state.queue.includes(op.id);b.onclick=()=>{state=engine.resolve(state!,op.id,decision);render();};cell.append(b);}}result.append(table);}
function safe(fn:()=>Promise<void>|void){return ()=>{void Promise.resolve().then(fn).catch(e=>{$('status').textContent=e.message;});};}
$('load').onclick=()=>{$<HTMLTextAreaElement>('graph').value=serialize(example($<HTMLSelectElement>('recipe').value as 'remove'));};$('load').click();
$('run').onclick=safe(async()=>{const graph=importEdit($<HTMLTextAreaElement>('graph').value);state=await engine.advance(engine.create(graph,{source:synthetic().media}));render();});$('continue').onclick=safe(async()=>{if(state){state=await engine.advance(engine.continue(state));render();}});
function download(blob:Blob,name:string){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('save').onclick=()=>{if(state)download(new Blob([serialize(state)],{type:'application/json'}),'pipeline-run.json');};$<HTMLInputElement>('restore').onchange=safe(async()=>{const file=$<HTMLInputElement>('restore').files?.[0];if(file){state=importRun(await file.text());render();}});
for(const kind of ['meeting','podcast','slideshow'] as const){const b=document.createElement('button');b.textContent=`Generate ${kind} MP4`;b.onclick=safe(async()=>{b.disabled=true;try{download(await sampleMedia(kind),`${kind}-synthetic.mp4`);}finally{b.disabled=false;}});$('samples').append(b);}
